function outfitStockContext(){
 if(!isOpenWorld())return {available:true,label:SOSText("economy_shops_commissions.outfitStockContext.001"),detail:SOSText("economy_shops_commissions.outfitStockContext.002"),locId:null};
 const locId=state.world.location,loc=worldLocation(locId);
 if(!isTownLikeLocation(loc))return {available:false,label:SOSText("economy_shops_commissions.outfitStockContext.003"),detail:SOSText("economy_shops_commissions.outfitStockContext.004",loc?.name||'this location'),locId};
 if(!settlementServiceAvailable(locId))return {available:false,label:SOSText("economy_shops_commissions.outfitStockContext.005"),detail:SOSText("economy_shops_commissions.outfitStockContext.006",loc.name),locId};
 const count=roundGearCandidates().length;
 return {available:count>0,label:SOSText("economy_shops_commissions.outfitStockContext.007"),detail:count?SOSText("economy_shops_commissions.outfitStockContext.008",count,count===1?'':'s',loc.name):SOSText("economy_shops_commissions.outfitStockContext.009",loc.name),locId,count}
}
function consumeOutfitCandidate(c){
 if(!c)return false;
 if(c.stockType==='local'){
  const rec=state.world.localStock?.[c.locId];if(!rec?.ids)return false;const idx=rec.ids.indexOf(c.it.id);if(idx<0)return false;rec.ids.splice(idx,1);return true
 }
 const arr=state.shopStock?.[c.source];if(!Array.isArray(arr))return false;const idx=arr.indexOf(c.it.id);if(idx<0)return false;arr.splice(idx,1);return true
}
function roundGearCandidates(){
 normalize();
 // Siege mode retains the campaign's current shop stock.
 if(!isOpenWorld()){
  const out=[];for(const [source,ids] of [['blacksmith',state.shopStock.blacksmith],['fletcher',state.shopStock.fletcher],['wizard',state.shopStock.wizard||[]],['market',state.shopStock.market]])ids.forEach(id=>{const it=item(id);if(it)out.push({source,stockType:'round',it,price:shopPrice(Math.round(it.price*(source==='market'?1.08:1)))})});return out
 }
 const locId=state.world.location,loc=worldLocation(locId);
 if(!isTownLikeLocation(loc)||!settlementServiceAvailable(locId))return [];
 if(locId==='shantium'){
  const out=[];for(const [source,ids] of [['blacksmith',state.shopStock.blacksmith],['fletcher',state.shopStock.fletcher],['wizard',state.shopStock.wizard||[]],['market',state.shopStock.market]])ids.forEach(id=>{const it=item(id);if(it)out.push({source,stockType:'shantium',locId,it,price:shopPrice(Math.round(it.price*(source==='market'?1.08:1)))})});return out
 }
 return ensureLocalStock(locId).map(id=>item(id)).filter(Boolean).map(it=>({source:'local',stockType:'local',locId,it,price:localEquipmentPrice(locId,it)}))
}
function resaleValue(it){return it?Math.max(1,Math.floor((it.price||0)*.5)):0}
function reclaimableOutfitValue(ownerId,candidate){
 const o=ownerFor(ownerId);if(!o||!candidate?.slot)return 0;const old=fitEffectiveItem(o.equipment?.[candidate.slot],ownerId);if(!old)return 0;const usefulElsewhere=['guardian',...state.allies].filter(x=>x!==ownerId&&ownerFor(x)).some(x=>gearUtility(old,ownerClassName(x),'balanced',x)>gearUtility(fitEffectiveItem(ownerFor(x).equipment?.[old.slot],x),ownerClassName(x),'balanced',x)+2);return usefulElsewhere?0:resaleValue(old)
}
function outfitReturn(returnTo,ownerId){
 if(returnTo==='party')return showParty();
 if(returnTo==='homeprep')return showHomePreparation();
 return showInventory(ownerId)
}
function showOutfitter(ownerId='guardian',returnTo='inventory'){modalRouteEnter(SOSText("economy_shops_commissions.showOutfitter.001"),Array.from(arguments));
 const ctx=outfitStockContext(),cls=ownerClassName(ownerId),avail=ctx.available?roundGearCandidates().length:0,backLabel=returnTo==='party'?'Back to Roster':returnTo==='homeprep'?'Back to Preparation':SOSText("economy_shops_commissions.showOutfitter.002");
 if(!ctx.available)return actionResult(SOSText("economy_shops_commissions.showOutfitter.003"),ctx.detail,'info',()=>outfitReturn(returnTo,ownerId));
 overlay(SOSText("economy_shops_commissions.showOutfitter.004",esc(ownerName(ownerId)),isOpenWorld()?`The company checks equipment actually offered by merchants in ${esc(worldLocation(state.world.location).name)}. No remote stock is used.`:'The quartermaster searches currently available campaign shop stock for useful upgrades and class-suited equipment.',avail,fmt(state.gold),state.gold,state.gold,state.gold,state.gold<=0||avail===0?'disabled':'',backLabel));
 $('#outfitBudget').oninput=()=>$('#budgetReadout').textContent=$('#outfitBudget').value;$('#runOutfit').onclick=()=>autoOutfit(ownerId,+$('#outfitBudget').value,$('#outfitPriority').value,returnTo);$('#backInventory').onclick=()=>outfitReturn(returnTo,ownerId)
}
function autoOutfit(ownerId,budget,priority,returnTo='inventory'){const owner=ownerFor(ownerId),cls=ownerClassName(ownerId),startGold=state.gold,isComp=ownerId!=='guardian',trust=isComp?companionTrust(owner):0,availablePersonal=isComp?Math.max(0,(owner.personalGold||0)-(owner.reserveGold||0)):0;let remaining=Math.min(budget,state.gold),spent=0,tradeCredit=0,personalSpent=0;const bought=[],usedSlots=new Set();const raw=roundGearCandidates().map(c=>{const current=item(owner.equipment[c.it.slot]),fit=roleSuitability(cls,c.it),improvement=gearUtility(c.it,cls,priority,ownerId)-gearUtility(current,cls,priority,ownerId),empty=!current;return {...c,current,fit,improvement,empty,ratio:improvement/Math.max(1,c.price)}}).filter(c=>c.improvement>1&&c.fit.ok);
 const sortUpgrade=(x,y)=>priority==='weapon'?(y.it.slot==='weapon')-(x.it.slot==='weapon')||y.ratio-x.ratio:priority==='defense'?(['armor','offhand','helm'].includes(y.it.slot)?1:0)-(['armor','offhand','helm'].includes(x.it.slot)?1:0)||y.ratio-x.ratio:priority==='cheap'?y.ratio-x.ratio:y.improvement-x.improvement;
 const empties=priority==='balanced'?raw.filter(c=>c.empty&&balancedEmptySlotCandidate(ownerId,c.it)).sort((x,y)=>y.fit.score-x.fit.score||gearUtility(y.it,cls,'balanced',ownerId)-gearUtility(x.it,cls,'balanced',ownerId)||x.price-y.price):[];
 const upgrades=raw.filter(c=>!c.empty||priority!=='balanced').sort(sortUpgrade);
 const candidates=priority==='balanced'?[...empties,...upgrades]:upgrades;
 for(const c of candidates){if(usedSlots.has(c.it.slot))continue;if(priority==='balanced'&&c.empty&&!balancedEmptySlotCandidate(ownerId,c.it))continue;if(priority==='balanced'&&!c.empty&&c.fit.score<0)continue;
   const credit=reclaimableOutfitValue(ownerId,c.it),net=Math.max(0,c.price-credit),short=Math.max(0,net-remaining),willingCap=isComp&&c.improvement>=5?Math.min(availablePersonal-personalSpent,Math.max(0,Math.round((owner.personalGold||0)*(trust>=75?.35:trust>=60?.25:.15)))):0;if(short>willingCap)continue;
   if(!consumeOutfitCandidate(c))continue;
   const selfPay=Math.max(0,net-remaining);personalSpent+=selfPay;remaining=Math.max(0,remaining-(net-selfPay));spent+=net-selfPay;tradeCredit+=credit;usedSlots.add(c.it.slot);
   const old=owner.equipment[c.it.slot];owner.equipment[c.it.slot]=c.it.id;if(old){if(credit>0)log(SOSText("economy_shops_commissions.autoOutfit.001",ownerName(ownerId),item(old).name,credit,c.it.name),'info');else redistributeOrSell(old,ownerId)}
   state.flags.purchases++;const why=c.empty?'fills an empty slot with appropriate gear':c.improvement>8?'strong upgrade':'upgrade';bought.push(SOSText("economy_shops_commissions.autoOutfit.002",c.it.name,ownerName(ownerId),c.price,credit?`, ${credit}g trade-in / ${net}g net`:'',why,c.fit.label,gearAffinity(cls,c.it)>0?', class-favored':''));
 }
 state.gold=startGold-spent;if(isComp&&personalSpent>0)owner.personalGold=Math.max(owner.reserveGold||0,(owner.personalGold||0)-personalSpent);if(bought.some(n=>/Guardian's|Shield of|Blackstone|Coalition Longbow|Verian|Sword of Shantium/.test(n)))unlock('legend');sfx(bought.length?'coin':'miss');log(bought.length?SOSText("economy_shops_commissions.autoOutfit.003",ownerName(ownerId),spent,tradeCredit?` after ${tradeCredit}g in trade-ins`:''):SOSText("economy_shops_commissions.autoOutfit.004",budget),bought.length?'good':'info');save();overlay(SOSText("economy_shops_commissions.autoOutfit.005",bought.length?`<div class="success notice">${bought.map(esc).join('<br>')}</div><p>Guardian allowance used: <b>${spent}g</b>${personalSpent?` • ${esc(owner.name)} voluntarily contributed <b>${personalSpent}g</b> and retains <b>${owner.personalGold}g</b>`:''}${tradeCredit?` • Trade-in value used: <b>${tradeCredit}g</b>`:''} • Gold remaining: <b>${state.gold}g</b></p>`:`<div class="notice">No worthwhile role-appropriate upgrades were found within this allowance. Empty slots are deliberately left empty when the available gear conflicts with the character's role.</div>`,returnTo==='party'?'Return to Roster':returnTo==='homeprep'?'Return to Preparation':'Return to Inventory'));$('#outfitDone').onclick=()=>outfitReturn(returnTo,ownerId)}
function redistributeOrSell(id,excludeId){const it=item(id);if(!it)return;let best=null,gain=1;for(const oid of ['guardian',...state.allies]){if(oid===excludeId)continue;const o=ownerFor(oid);if(!o)continue;const d=gearUtility(it,ownerClassName(oid))-gearUtility(item(o.equipment[it.slot]),ownerClassName(oid));if(d>gain){gain=d;best=oid}}if(best){const o=ownerFor(best),old=o.equipment[it.slot];o.equipment[it.slot]=id;if(old)redistributeOrSell(old,best);log(SOSText("economy_shops_commissions.redistributeOrSell.001",it.name,ownerName(best)),'good')}else{const v=Math.max(1,Math.round((it.price||10)*.45));gainGold(v);log(SOSText("economy_shops_commissions.redistributeOrSell.002",it.name,v),'info')}}
function availableGear(shop){let maxTier=state.round<=3?1:state.round<=6?3:state.round<=9?5:7;if(state.flags.shopPenalty)maxTier=Math.max(1,maxTier-1);let list=ITEMS.filter(i=>i.tier<=maxTier);if(shop===SOSText("economy_shops_commissions.availableGear.001"))list=list.filter(i=>!i.magic&&['weapon','offhand','armor','helm','boots'].includes(i.slot)&&!/(Bow|Crossbow)/i.test(i.name));else if(shop===SOSText("economy_shops_commissions.availableGear.002"))list=list.filter(i=>!i.magic&&(/Bow|Crossbow/i.test(i.name)||i.slot==='boots'));else if(shop===SOSText("economy_shops_commissions.availableGear.003"))list=list.filter(i=>i.magic||i.slot==='amulet'||i.slot==='ring');return list.sort(()=>Math.random()-.5).slice(0,12)}
function makeRoundShopStock(){const maxMarketTier=Math.min(7,1+Math.floor(state.round/2));const blacksmith=availableGear(SOSText("economy_shops_commissions.makeRoundShopStock.001")).map(i=>i.id),fletcher=availableGear(SOSText("economy_shops_commissions.makeRoundShopStock.002")).map(i=>i.id),wizard=availableGear(SOSText("economy_shops_commissions.makeRoundShopStock.003")).map(i=>i.id);let marketPool=ITEMS.filter(i=>i.tier<=maxMarketTier&&!i.magic);const jewelry=marketPool.filter(i=>['ring','amulet'].includes(i.slot)).sort(()=>Math.random()-.5).slice(0,state.round>=4?2:1);const general=marketPool.filter(i=>!['ring','amulet'].includes(i.slot)).sort(()=>Math.random()-.5).slice(0,5);let rare=[];const rareChance=.18+Math.min(.32,(state.flags.marketFavor||0)*.16);if(chance(rareChance)){const rp=ITEMS.filter(i=>i.tier===Math.min(7,maxMarketTier+1)&&!i.id.startsWith('named_'));if(rp.length)rare=[pick(rp)]}if(state.flags.marketFavor>0)state.flags.marketFavor--;const market=[...new Set([...jewelry,...general,...rare])].map(i=>i.id);const apothecary={};CONSUMABLES.forEach(i=>apothecary[i.id]=rnd(1,3)+(i.id==='heal'||i.id==='bandage'?1:0));const damaged=state.townCondition?.damaged||{};const trim=(arr,id)=>damaged[id]?arr.slice(0,Math.max(1,arr.length-damaged[id]*2)):arr;return {round:state.round,blacksmith:trim(blacksmith,'blacksmith'),fletcher:trim(fletcher,'fletcher'),wizard:trim(wizard,'wizard'),market:trim(market,'market'),apothecary,storehouse:{food:2,medicine:2,timber:2,stone:2}}}

