function commissionShopKey(shop){return shop===SOSText("economy_shops_commissions.commissionShopKey.001")?'blacksmith':shop===SOSText("economy_shops_commissions.commissionShopKey.002")?'fletcher':'wizard'}
function commissionAvailablePool(shop,recipient,interest){const cls=ownerClassName(recipient),level=recipient==='guardian'?state.level:(state.party.members[recipient]?.level||state.level),cap=Math.min(7,Math.max(1,Math.floor((state.round+level)/3)));let pool=ITEMS.filter(i=>i.tier<=cap&&!i.id.startsWith('named_'));if(shop===SOSText("economy_shops_commissions.commissionAvailablePool.001"))pool=pool.filter(i=>!i.magic&&['weapon','armor','offhand','helm','boots'].includes(i.slot)&&![SOSText("economy_shops_commissions.commissionAvailablePool.002"),SOSText("economy_shops_commissions.commissionAvailablePool.003"),SOSText("economy_shops_commissions.commissionAvailablePool.004")].includes(weaponFamily(i)));if(shop===SOSText("economy_shops_commissions.commissionAvailablePool.005"))pool=pool.filter(i=>!i.magic&&([SOSText("economy_shops_commissions.commissionAvailablePool.006"),SOSText("economy_shops_commissions.commissionAvailablePool.007"),SOSText("economy_shops_commissions.commissionAvailablePool.008")].includes(weaponFamily(i))||(['armor','boots'].includes(i.slot)&&armorWeight(i)!==SOSText("economy_shops_commissions.commissionAvailablePool.009"))));if(shop===SOSText("economy_shops_commissions.commissionAvailablePool.010"))pool=pool.filter(i=>i.magic||['ring','amulet'].includes(i.slot));if(interest==='weapon')pool=pool.filter(i=>i.slot==='weapon');if(interest==='armor')pool=pool.filter(i=>['armor','offhand','helm','boots'].includes(i.slot));if(interest==='jewelry')pool=pool.filter(i=>['ring','amulet'].includes(i.slot));return pool.sort((a,b)=>gearUtility(b,cls,'balanced')-gearUtility(a,cls,'balanced'))}
function makeCommissionState(){const damaged=state.townCondition?.damaged||{},result={round:state.round};for(const [key,shop] of [['blacksmith',SOSText("economy_shops_commissions.makeCommissionState.001")],['fletcher',SOSText("economy_shops_commissions.makeCommissionState.002")],['wizard',SOSText("economy_shops_commissions.makeCommissionState.003")]]){const avail=!damaged[key]&&chance(.10),master=avail&&chance(.12);result[key]={available:avail,master,remaining:avail?(chance(.18)?2:1):0,menus:{}}}return result}
