function showCommissionInterests(shop,recipient){modalRouteEnter(SOSText("economy_shops_commissions.showCommissionInterests.001"),Array.from(arguments));const jewelry=shop===SOSText("economy_shops_commissions.showCommissionInterests.002")?SOSText("economy_shops_commissions.showCommissionInterests.003"):'';overlay(SOSText("economy_shops_commissions.showCommissionInterests.004",shop,jewelry));document.querySelectorAll('[data-cinterest]').forEach(b=>b.onclick=()=>showCommissionOptions(shop,recipient,b.dataset.cinterest));$('#commissionBack').onclick=()=>SOSServices.navigation.back(()=>showCommissionRecipients(shop))}
