function equipmentSaleContext(){
 if(!isOpenWorld())return{allowed:true,locId:null,prosperity:50,mult:1,label:'Siege market'};
 const locId=state.world?.location,loc=worldLocation(locId),settlement=!!state.world?.settlements?.[locId];
 if(!settlement)return{allowed:false,locId,prosperity:0,mult:0,label:'No local buyers'};
 if(!settlementServiceAvailable(locId))return{allowed:false,locId,prosperity:settlementState(locId).prosperity||0,mult:0,label:'Local trade unavailable'};
 const prosperity=clamp(Math.round(settlementState(locId).prosperity||50),0,100),mult=clamp(.75+prosperity/200,.75,1.25);
 return{allowed:true,locId,prosperity,mult,label:prosperity>=75?'Strong market':prosperity>=55?'Healthy market':prosperity>=35?'Weak market':'Poor market'}
}
function equipmentSellPrice(it){
 const ctx=equipmentSaleContext();return Math.max(1,Math.round((it?.price||10)*.45*(ctx.allowed?ctx.mult:1)))
}
function equipmentSaleMarketNote(){
 const c=equipmentSaleContext();if(!isOpenWorld())return'';
 if(!c.allowed)return SOSText("economy_shops_commissions.equipmentSaleMarketNote.001");
 const pct=Math.round((c.mult-1)*100),sign=pct>0?'+':'';
 return SOSText("economy_shops_commissions.equipmentSaleMarketNote.002",esc(worldLocation(c.locId).name),c.prosperity,esc(c.label),sign,pct)
}
function blockEquipmentSaleIfUnavailable(after){
 const c=equipmentSaleContext();if(c.allowed)return false;
 actionResult(SOSText("economy_shops_commissions.blockEquipmentSaleIfUnavailable.001"),SOSText("economy_shops_commissions.blockEquipmentSaleIfUnavailable.002"),'info',after||renderOpenWorld);return true
}
