function showMason(){modalRouteEnter(SOSText("economy_shops_commissions.showMason.001"),Array.from(arguments));overlay(SOSText("economy_shops_commissions.showMason.002",state.gold,state.town.timber,state.town.stone,UPGRADES.map(u=>`<div class="card"><h4>${u.name}</h4><p>${u.desc}</p><div class="price">${u.price} gold</div><button data-upgrade="${u.id}" ${state.town.upgrades.includes(u.id)||state.gold<u.price?'disabled':''}>${state.town.upgrades.includes(u.id)?'Built':'Build'}</button></div>`).join(''),footer()),true);document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>buildUpgrade(b.dataset.upgrade));wireClose()}
function buildUpgrade(id){const u=UPGRADES.find(x=>x.id===id);if(!u||state.town.upgrades.includes(id))return;if(pay(state,u.price)){state.town.upgrades.push(id);applyUpgrade(id);sfx('repair');log(`${u.name} completed.`,'good');save()}showMason()}
function applyUpgrade(id){const t=state.town;if(id==='palisade'){t.maxWalls+=25;t.walls+=25}if(id==='stonework'){t.maxWalls+=35;t.walls+=35}if(id==='gatehouse'){t.maxGate+=30;t.gate+=30}if(id===SOSText("economy_shops_commissions.applyUpgrade.001")){t.maxGate+=20;t.gate+=20}if(id==='watchtower'||id===SOSText("economy_shops_commissions.applyUpgrade.002"))gainScouting(1);}
function showStorehouse(){modalRouteEnter(SOSText("economy_shops_commissions.showStorehouse.001"),Array.from(arguments));normalize();const ss=state.shopStock.storehouse;const stockLabel=(n)=>n>0?SOSText("economy_shops_commissions.showStorehouse.002",n,n===1?'':'s'):SOSText("economy_shops_commissions.showStorehouse.003");overlay(SOSText("economy_shops_commissions.showStorehouse.004",townPanel(),ss.food&&state.gold>=35?'':'disabled',stockLabel(ss.food),ss.medicine&&state.gold>=40?'':'disabled',stockLabel(ss.medicine),ss.timber&&state.gold>=38?'':'disabled',stockLabel(ss.timber),ss.stone&&state.gold>=42?'':'disabled',stockLabel(ss.stone),state.gold<45||state.town.population<=10?'disabled':'',state.gold<50||state.town.timber<6?'disabled':'',state.gold<42||state.town.timber<4?'disabled':'',footer()));$('#buyFood').onclick=()=>resAction(35,()=>state.town.food+=12,'food');$('#buyMed').onclick=()=>resAction(40,()=>state.town.medicine+=8,'medicine');$('#buyTimber').onclick=()=>resAction(38,()=>state.town.timber+=12,'timber');$('#buyStone').onclick=()=>resAction(42,()=>state.town.stone+=10,'stone');$('#recruit').onclick=()=>resAction(45,()=>{if(state.town.population>10){state.town.militia+=4;state.town.population-=2}});$('#repairWalls').onclick=()=>{if(state.town.timber>=6&&pay(state,50)){state.town.timber-=6;state.town.walls+=20;sfx('repair');save()}showStorehouse()};$('#repairGate').onclick=()=>{if(state.town.timber>=4&&pay(state,42)){state.town.timber-=4;state.town.gate+=15;sfx('repair');save()}showStorehouse()};wireClose()}

function resAction(cost,fn,stockKey=null){if(stockKey&&state.shopStock.storehouse[stockKey]<=0)return showStorehouse();if(pay(state,cost)){fn();if(stockKey)state.shopStock.storehouse[stockKey]--;sfx('coin');save()}showStorehouse()}
