function showCouncil(){modalRouteEnter(SOSText("economy_shops_commissions.showCouncil.001"),Array.from(arguments));if(isOpenWorld())return showOpenWorldCouncilHall();overlay(SOSText("economy_shops_commissions.showCouncil.002",Object.entries(state.relations).map(([k,v])=>`<div class="stat-row"><span>${k}</span><b>${v>=0?'+':''}${v}</b></div>`).join(''),state.gold<35?'disabled':'',state.gold<45?'disabled':'',prisonerCount(),NPCS.slice(0,6).map(n=>`<div class="card"><b>${n[0]}</b><br><small>${n[1]}</small></div>`).join(''),footer()),true);$('#rally').onclick=()=>{if(pay(state,35)){state.town.morale+=6;save()}showCouncil()};$('#draft').onclick=()=>{state.town.militia+=7;state.town.morale-=7;state.town.population-=4;save();showCouncil()};$('#scouts').onclick=()=>{if(pay(state,45)){gainScouting(1);save()}showCouncil()};$('#prisonersBtn').onclick=showPrisoners;wireClose()}

function compositionReport(gr){const counts={};gr.members.forEach(e=>counts[e.name]=(counts[e.name]||0)+1);return Object.entries(counts).map(([name,n])=>`${n>1?`<b>${n}×</b> `:''}${esc(name)}`).join('<br>')}
function prisonerCount(){return (state.prisoners||[]).reduce((n,p)=>n+(p.count||0),0)}
function partyPrisoners(){return (state.prisoners||[]).filter(p=>!p.hallCustody)}
function hallPrisoners(){return (state.prisoners||[]).filter(p=>!!p.hallCustody)}
function partyPrisonerCount(){return partyPrisoners().reduce((n,p)=>n+(p.count||0),0)}
function hallPrisonerCount(){return hallPrisoners().reduce((n,p)=>n+(p.count||0),0)}

function partyDeterrence(){return state.level*2+stat(state,'cha')*.7+partyMembers(true).filter(m=>m.hp>0).length*3+Math.floor(state.town.morale/25)}
function canDemandSurrender(gr){return !gr.commander&&gr.members.length<=4&&state.roundActions>0&&(partyDeterrence()>=gr.members.length*3+5||stat(state,'cha')>=12)}
